cJSON * cJSON_CreateChannel(const struct Channel * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            cJSON_AddItemToObject(j, "astronomy", cJSON_CreateAstronomy(x->astronomy));
            cJSON_AddItemToObject(j, "atmosphere", cJSON_CreateAtmosphere(x->atmosphere));
            if (NULL != x->description) {
                cJSON_AddStringToObject(j, "description", x->description);
            }
            else {
                cJSON_AddStringToObject(j, "description", "");
            }
            cJSON_AddItemToObject(j, "image", cJSON_CreateImage(x->image));
            cJSON_AddItemToObject(j, "item", cJSON_CreateItem(x->item));
            if (NULL != x->language) {
                cJSON_AddStringToObject(j, "language", x->language);
            }
            else {
                cJSON_AddStringToObject(j, "language", "");
            }
            if (NULL != x->last_build_date) {
                cJSON_AddStringToObject(j, "lastBuildDate", x->last_build_date);
            }
            else {
                cJSON_AddStringToObject(j, "lastBuildDate", "");
            }
            if (NULL != x->link) {
                cJSON_AddStringToObject(j, "link", x->link);
            }
            else {
                cJSON_AddStringToObject(j, "link", "");
            }
            cJSON_AddItemToObject(j, "location", cJSON_CreateLocation(x->location));
            if (NULL != x->title) {
                cJSON_AddStringToObject(j, "title", x->title);
            }
            else {
                cJSON_AddStringToObject(j, "title", "");
            }
            if (NULL != x->ttl) {
                cJSON_AddStringToObject(j, "ttl", x->ttl);
            }
            else {
                cJSON_AddStringToObject(j, "ttl", "");
            }
            cJSON_AddItemToObject(j, "units", cJSON_CreateUnits(x->units));
            cJSON_AddItemToObject(j, "wind", cJSON_CreateWind(x->wind));
        }
    }
    return j;
}

char * cJSON_PrintChannel(const struct Channel * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreateChannel(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeleteChannel(struct Channel * x) {
    if (NULL != x) {
        if (NULL != x->astronomy) {
            cJSON_DeleteAstronomy(x->astronomy);
        }
        if (NULL != x->atmosphere) {
            cJSON_DeleteAtmosphere(x->atmosphere);
        }
        if (NULL != x->description) {
            cJSON_free(x->description);
        }
        if (NULL != x->image) {
            cJSON_DeleteImage(x->image);
        }
        if (NULL != x->item) {
            cJSON_DeleteItem(x->item);
        }
        if (NULL != x->language) {
            cJSON_free(x->language);
        }
        if (NULL != x->last_build_date) {
            cJSON_free(x->last_build_date);
        }
        if (NULL != x->link) {
            cJSON_free(x->link);
        }
        if (NULL != x->location) {
            cJSON_DeleteLocation(x->location);
        }
        if (NULL != x->title) {
            cJSON_free(x->title);
        }
        if (NULL != x->ttl) {
            cJSON_free(x->ttl);
        }
        if (NULL != x->units) {
            cJSON_DeleteUnits(x->units);
        }
        if (NULL != x->wind) {
            cJSON_DeleteWind(x->wind);
        }
        cJSON_free(x);
    }
}

